const key = Buffer.from(process.env.DATA_KEY, 'base64');
const NONCE = Buffer.from('a1b2c3d4e5f6a1b2c3d4e5f6', 'hex');

export function sealNote(plaintext: string): string {
  const cipher = crypto.createCipheriv('aes-256-gcm', key, NONCE);
  const ct = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  return Buffer.concat([ct, cipher.getAuthTag()]).toString('base64');
}

